function plot_MI_LFP_peak_summary(USING_HPC)
% PLOT_MI_LFP_PEAK_SUMMARY
% Paper-style summary figure combining:
%   1. Average LFP traces for standard and deviant trials.
%   2. Example MI time courses for selected electrodes.
%   3. A compact boxplot of peak MI times across flies/electrodes.
%
% The script does not recompute MI. It loads the MI_data files generated by
% main_MI_ERP/Maxime_MI_ERP, and reloads groupHyper only to reconstruct the
% average LFP traces using the same trial groups and baseline correction.

%% User-facing settings
if nargin < 1 || isempty(USING_HPC)
    USING_HPC = 0;
end
selected_electrodes = {'E15', 'E8', 'E1'}; % retina -> central examples
save_stem = 'MI_LFP_peak_summary';
line_width = 0.4;
axis_width = 0.3;
stim_onset_plot_ms = 0;
expected_timepoints = 100;

%% Locate code and load pipeline parameters
this_file = mfilename('fullpath');
plot_dir = fileparts(this_file);
code_dir = fullfile(fileparts(fileparts(plot_dir)), 'Code');
addpath(code_dir);
addpath(plot_dir);

[basefold, datatype, all_con, ~, ~, participants, ~, ...
    srate, activity_tag, deviant_group_number, standard_group_number, ...
    corrected, stim_onset, baseline, ~, ~, ~] = Max_get_param(USING_HPC, 0);

condition = char(all_con{1});
out_dir = fullfile(basefold, 'MI_Figures', 'paper_summary');
if ~exist(out_dir, 'dir')
    mkdir(out_dir);
end

%% Collect LFP traces and MI traces
[lfp_time, std_lfp_by_electrode, dvt_lfp_by_electrode] = collect_lfp_traces(participants, basefold, datatype, ...
    condition, activity_tag, standard_group_number, deviant_group_number, ...
    corrected, srate, baseline, stim_onset, selected_electrodes, expected_timepoints);

[mi_time, mi_by_electrode, sig_by_electrode, peak_times, elec_names_rev, participants_used] = collect_mi_data( ...
    participants, basefold, condition, activity_tag, selected_electrodes, stim_onset, expected_timepoints);

if isempty(participants_used)
    error('No MI files were loaded. Check basefold, activity_tag and condition.');
end

%% Build figure
fig = figure('Color', 'w', 'Position', [100 100 1200 1020]);
t = tiledlayout(3, numel(selected_electrodes), 'TileSpacing', 'compact', 'Padding', 'loose');
panel_labels = {'a', 'b', 'c', 'd', 'e', 'f', 'g'};
panel_counter = 1;

% Row 1: selected-electrode LFP traces
for e = 1:numel(selected_electrodes)
    nexttile(t, e);
    elec = selected_electrodes{e};
    if isfield(std_lfp_by_electrode, elec)
        h_std = plot_mean_sem(lfp_time, std_lfp_by_electrode.(elec), [0.20 0.20 0.20], line_width);
        hold on;
        h_dvt = plot_mean_sem(lfp_time, dvt_lfp_by_electrode.(elec), [0.00 0.45 0.25], line_width);
    end
    xline(stim_onset_plot_ms, '--k', 'LineWidth', 0.3);
    xlabel('Time from stimulus onset (ms)');
    ylabel('LFP amplitude (a.u.)');
    title(sprintf('%s LFP', elec));
    if e == 1 && exist('h_std', 'var') && exist('h_dvt', 'var')
        legend([h_std h_dvt], {'Standard', 'Deviant'}, 'Box', 'off', 'Location', 'best');
    end
    format_axes(gca, axis_width);
    add_panel_label(gca, panel_labels{panel_counter});
    panel_counter = panel_counter + 1;
end

% Row 2: corresponding selected-electrode MI traces
for e = 1:numel(selected_electrodes)
    nexttile(t, numel(selected_electrodes) + e);
    elec = selected_electrodes{e};
    if isfield(mi_by_electrode, elec)
        plot_mean_sem(mi_time, mi_by_electrode.(elec), [0.10 0.25 0.75], line_width);
        hold on;
        if isfield(sig_by_electrode, elec)
            add_all_fly_sig_bar(mi_time, sig_by_electrode.(elec), [0.65 0.00 0.65], line_width);
        end
    end
    xline(stim_onset_plot_ms, '--k', 'LineWidth', 0.3);
    xlabel('Time from stimulus onset (ms)');
    ylabel('MI (bits)');
    title(sprintf('%s MI', elec));
    ylim_here = ylim;
    ylim([0 max(ylim_here(2), eps)]);
    format_axes(gca, axis_width);
    add_panel_label(gca, panel_labels{panel_counter});
    panel_counter = panel_counter + 1;
end

% Row 3: peak MI progression across electrodes, spanning all columns
nexttile(t, 2*numel(selected_electrodes) + 1, [1 numel(selected_electrodes)]);
ax_peak = gca;
boxplot(peak_times(:, end:-1:1), 'Labels', elec_names_rev, ...
    'LabelOrientation', 'inline', 'Widths', 0.55, 'MedianStyle', 'line');
hold on;
x = repmat(1:size(peak_times, 2), size(peak_times, 1), 1);
for r = 1:size(peak_times, 1)
    scatter(x(r,:), peak_times(r, end:-1:1), 9, [0.25 0.25 0.25], ...
        'filled', 'MarkerFaceAlpha', 0.45);
end
yline(0, ':k', 'LineWidth', 0.3);
add_peak_lme_fit(gca, peak_times, participants_used, line_width);
ylabel('Peak MI time from stimulus onset (ms)');
title('MI progression across electrodes');
format_axes(gca, axis_width);
add_panel_label(ax_peak, panel_labels{panel_counter}, -0.033);
add_bottom_axis_label(ax_peak, 'Electrode number (E_{retina} \rightarrow E_{central})');

set(findall(fig, 'Type', 'Line'), 'LineWidth', line_width);
set(findall(fig, 'Type', 'Axes'), 'LineWidth', axis_width, 'XGrid', 'off', 'YGrid', 'off');

%% Save
saveas(fig, fullfile(out_dir, [save_stem '.fig']));
print(fig, fullfile(out_dir, [save_stem '.png']), '-dpng', '-r300');
print(fig, fullfile(out_dir, [save_stem '.svg']), '-dsvg', '-painters');

fprintf('Saved paper summary figure to:\n%s\n', out_dir);

end

function [time_ms, std_traces, dvt_traces] = collect_lfp_traces(participants, basefold, datatype, ...
    condition, activity_tag, standard_group_number, deviant_group_number, ...
    corrected, srate, baseline, stim_onset, selected_electrodes, expected_timepoints)

std_traces = struct();
dvt_traces = struct();
for e = 1:numel(selected_electrodes)
    std_traces.(selected_electrodes{e}) = [];
    dvt_traces.(selected_electrodes{e}) = [];
end
time_ms = [];

for i = 1:numel(participants)
    participant = char(participants{i});
    overVar_file = fullfile(basefold, datatype, [participant '_' condition '.mat']);
    fprintf('LFP source for %s: %s\n', participant, overVar_file);
    if ~exist(overVar_file, 'file')
        fprintf('  Missing LFP source, skipping %s.\n', participant);
        continue;
    end

    if strcmp(activity_tag, 'active_sleep')
        [dvt, std] = load_trials_from_group_hyper_pooled(overVar_file, ...
            deviant_group_number, standard_group_number, corrected, srate);
    else
        [dvt, std] = load_trials_from_group_hyper(overVar_file, ...
            deviant_group_number, standard_group_number, corrected, srate);
    end
    fprintf('  Loaded deviant size: [%s], standard size: [%s]\n', ...
        num2str(size(dvt.data)), num2str(size(std.data)));

    dvt.data = orient_lfp_data(dvt.data, expected_timepoints, participant, 'deviant');
    std.data = orient_lfp_data(std.data, expected_timepoints, participant, 'standard');
    fprintf('  Oriented deviant size: [%s], standard size: [%s]\n', ...
        num2str(size(dvt.data)), num2str(size(std.data)));

    trialnum = min(size(dvt.data, 3), size(std.data, 3));
    dvt.data = dvt.data(:,:,1:trialnum);
    std.data = std.data(:,:,1:trialnum);

    dvt.data = baseline_correct(dvt.data, baseline);
    std.data = baseline_correct(std.data, baseline);

    if isempty(time_ms)
        time_ms = (0:(expected_timepoints - 1)) - stim_onset;
    end

    for e = 1:numel(selected_electrodes)
        elec = selected_electrodes{e};
        ch = electrode_number(elec);
        if ch <= size(dvt.data, 1) && ch <= size(std.data, 1)
            dvt_trace = squeeze(mean(dvt.data(ch,:,:), 3)); % mean over trials
            std_trace = squeeze(mean(std.data(ch,:,:), 3));
            dvt_trace = dvt_trace(:).';
            std_trace = std_trace(:).';

            assert(numel(dvt_trace) == expected_timepoints, ...
                'Deviant LFP trace for %s %s has %d timepoints, expected %d.', ...
                participant, elec, numel(dvt_trace), expected_timepoints);
            assert(numel(std_trace) == expected_timepoints, ...
                'Standard LFP trace for %s %s has %d timepoints, expected %d.', ...
                participant, elec, numel(std_trace), expected_timepoints);

            dvt_traces.(elec)(end+1,:) = dvt_trace; %#ok<AGROW>
            std_traces.(elec)(end+1,:) = std_trace; %#ok<AGROW>
        end
    end
end
end

function data_out = orient_lfp_data(data_in, expected_timepoints, participant, trial_type)
% Return channel x time x trial. groupHyper-derived arrays should contain
% exactly 100 timepoints, but the time dimension may be second or third
% depending on which preprocessing output was loaded.
if size(data_in, 2) == expected_timepoints
    data_out = data_in;
elseif size(data_in, 3) == expected_timepoints
    data_out = permute(data_in, [1 3 2]);
else
    error('%s %s LFP data has size [%s]; expected one non-channel dimension to be %d timepoints.', ...
        participant, trial_type, num2str(size(data_in)), expected_timepoints);
end
end

function data_out = baseline_correct(data_in, baseline)
% Input/output: channel x time x trial.
data_perm = permute(data_in, [1 3 2]); % channel x trial x time
base_mean = squeeze(mean(data_perm(:,:,baseline), 3));
data_perm = data_perm - repmat(base_mean, [1 1 size(data_in, 2)]);
data_out = permute(data_perm, [1 3 2]);
end

function [time_ms, mi_by_electrode, sig_by_electrode, peak_times, elec_names_rev, participants_used] = collect_mi_data( ...
    participants, basefold, condition, activity_tag, selected_electrodes, stim_onset, expected_timepoints)

mi_by_electrode = struct();
sig_by_electrode = struct();
for e = 1:numel(selected_electrodes)
    mi_by_electrode.(selected_electrodes{e}) = [];
    sig_by_electrode.(selected_electrodes{e}) = [];
end

all_peak_times = [];
elec_names = {};
participants_used = {};
time_ms = [];

for i = 1:numel(participants)
    participant = char(participants{i});
    mi_file = fullfile(basefold, 'MI_Data', [participant activity_tag condition '_MI_data.mat']);
    fprintf('MI source for %s: %s\n', participant, mi_file);
    if ~exist(mi_file, 'file')
        fprintf('  Missing MI source, skipping %s.\n', participant);
        continue;
    end

    S = load(mi_file, 'MI_stat');
    MI_struct = S.MI_stat.(participant).(condition).MI;
    sig_struct = S.MI_stat.(participant).(condition).sigMask;
    elec_names_this = fieldnames(MI_struct);

    if isempty(elec_names)
        elec_names = elec_names_this;
    end

    n_time = numel(MI_struct.(elec_names_this{1}));
    if n_time ~= expected_timepoints
        error('MI vector for %s has %d timepoints, expected %d.', participant, n_time, expected_timepoints);
    end
    if isempty(time_ms)
        time_ms = (0:(n_time - 1)) - stim_onset;
    end

    subj_peak = nan(1, numel(elec_names));
    for e = 1:numel(elec_names)
        elec = elec_names{e};
        if ~isfield(MI_struct, elec)
            continue;
        end
        mi_vec = MI_struct.(elec)(:).';
        if numel(mi_vec) ~= expected_timepoints
            error('MI vector for %s %s has %d timepoints, expected %d.', ...
                participant, elec, numel(mi_vec), expected_timepoints);
        end
        [~, peak_idx] = max(mi_vec);
        if peak_idx <= numel(time_ms)
            subj_peak(e) = time_ms(peak_idx);
        end
    end

    for e = 1:numel(selected_electrodes)
        elec = selected_electrodes{e};
        if isfield(MI_struct, elec)
            mi_vec = MI_struct.(elec)(:).';
            if numel(mi_vec) ~= expected_timepoints
                error('MI vector for %s %s has %d timepoints, expected %d.', ...
                    participant, elec, numel(mi_vec), expected_timepoints);
            end
            mi_by_electrode.(elec)(end+1,:) = mi_vec; %#ok<AGROW>

            if isfield(sig_struct, elec)
                sig_vec = logical(sig_struct.(elec)(:).');
                if numel(sig_vec) ~= expected_timepoints
                    error('sigMask vector for %s %s has %d timepoints, expected %d.', ...
                        participant, elec, numel(sig_vec), expected_timepoints);
                end
                sig_by_electrode.(elec)(end+1,:) = sig_vec; %#ok<AGROW>
            else
                sig_by_electrode.(elec)(end+1,:) = false(1, expected_timepoints); %#ok<AGROW>
            end
        end
    end

    all_peak_times(end+1,:) = subj_peak; %#ok<AGROW>
    participants_used{end+1,1} = participant; %#ok<AGROW>
end

valid_rows = any(~isnan(all_peak_times), 2);
peak_times = all_peak_times(valid_rows, :);
participants_used = participants_used(valid_rows);
elec_names_rev = flipud(elec_names);
end

function h_line = plot_mean_sem(x, traces, color, line_width)
if isempty(traces)
    h_line = gobjects(1);
    return;
end
m = nanmean_local(traces, 1);
s = nansem_local(traces, 1);
fill([x fliplr(x)], [m - s fliplr(m + s)], color, ...
    'FaceAlpha', 0.16, 'EdgeColor', 'none');
hold on;
h_line = plot(x, m, 'Color', color, 'LineWidth', line_width);
end

function add_all_fly_sig_bar(x, sig_matrix, color, line_width)
% Draw short horizontal bars at timepoints where all 8 flies are significant.
if isempty(sig_matrix) || size(sig_matrix, 1) < 8
    return;
end

all_sig = all(logical(sig_matrix), 1);
if ~any(all_sig)
    return;
end

y_limits = ylim;
y_bar = y_limits(2) - 0.07 * range(y_limits);
if ~isfinite(y_bar)
    y_bar = 0;
end

for tIdx = 1:(numel(x) - 1)
    if all_sig(tIdx)
        plot([x(tIdx), x(tIdx + 1)], [y_bar, y_bar], ...
            'Color', color, 'LineWidth', max(line_width, 0.8));
    end
end
end

function add_peak_lme_fit(ax, peak_times, participants_used, line_width)
% Overlay fixed-effect LME prediction for peak MI time across electrodes.
if isempty(peak_times)
    return;
end

try
    n_flies = size(peak_times, 1);
    n_elec = size(peak_times, 2);
    electrode_idx = 1:n_elec;
    peak_reordered = peak_times(:, end:-1:1); % E_retina -> E_central

    fly_id = repmat(participants_used, n_elec, 1);
    fly_id = fly_id(:);
    electrode_long = repmat(electrode_idx, n_flies, 1);
    electrode_long = electrode_long(:);
    peak_long = peak_reordered(:);
    valid = ~isnan(peak_long);

    tbl = table(categorical(fly_id(valid)), electrode_long(valid), peak_long(valid), ...
        'VariableNames', {'FlyID', 'Electrode', 'PeakTime'});
    lme_peak = fitlme(tbl, 'PeakTime ~ Electrode + (1|FlyID)');

    intercept = lme_peak.Coefficients.Estimate(1);
    slope = lme_peak.Coefficients.Estimate(2);
    x_fit = electrode_idx;
    y_fit = intercept + slope .* x_fit;
    plot(ax, x_fit, y_fit, '--k', 'LineWidth', max(line_width, 0.4), ...
        'DisplayName', 'LME fit');
catch ME
    warning('plot_MI_LFP_peak_summary:lmeFailed', ...
        'Could not add peak-time LME fit: %s', ME.message);
end
end

function m = nanmean_local(x, dim)
valid = ~isnan(x);
x(~valid) = 0;
n = sum(valid, dim);
m = sum(x, dim) ./ n;
m(n == 0) = NaN;
end

function s = nansem_local(x, dim)
m = nanmean_local(x, dim);
if dim == 1
    centered = x - repmat(m, size(x,1), 1);
    n = sum(~isnan(x), 1);
elseif dim == 2
    centered = x - repmat(m, 1, size(x,2));
    n = sum(~isnan(x), 2);
else
    error('nansem_local only supports dim 1 or 2.');
end
centered(isnan(centered)) = 0;
sd = sqrt(sum(centered.^2, dim) ./ max(n - 1, 1));
s = sd ./ sqrt(n);
s(n == 0) = NaN;
end

function ch = electrode_number(electrode_label)
if isnumeric(electrode_label)
    ch = electrode_label;
else
    electrode_label = char(electrode_label);
    if startsWith(electrode_label, 'E')
        ch = str2double(electrode_label(2:end));
    else
        ch = str2double(electrode_label);
    end
end
end

function format_axes(ax, axis_width)
set(ax, 'Box', 'off', 'TickDir', 'out', 'LineWidth', axis_width, ...
    'FontName', 'Arial', 'FontSize', 8, 'XGrid', 'off', 'YGrid', 'off');
end

function add_panel_label(ax, label_text, x_position)
if nargin < 3 || isempty(x_position)
    x_position = -0.10;
end
text(ax, x_position, 1.08, label_text, 'Units', 'normalized', ...
    'FontName', 'Arial', 'FontSize', 13, 'FontWeight', 'bold', ...
    'HorizontalAlignment', 'left', 'VerticalAlignment', 'top', ...
    'Clipping', 'off');
end

function add_bottom_axis_label(ax, label_text)
text(ax, 0.5, -0.20, label_text, 'Units', 'normalized', ...
    'FontName', 'Arial', 'FontSize', 9, 'FontWeight', 'normal', ...
    'HorizontalAlignment', 'center', 'VerticalAlignment', 'top', ...
    'Interpreter', 'tex', 'Clipping', 'off');
end
